public boolean shouldPrintMessage(int timestamp, String message) {
    // Check if the timestamp is within the specified range
    if (timestamp < 0 || timestamp > 24 * 60 * 60) {
        // If the timestamp is not within the range, print an error message
        System.err.println("Invalid timestamp: " + timestamp);
        return false;
    }

    // Check if the message is not null or empty
    if (message == null || message.isEmpty()) {
        // If the message is null or empty, print an error message
        System.err.println("Invalid message: " + message);
        return false;
    }

    // Check if the message should be printed based on the timestamp
    int hour = timestamp / 3600;
    int minute = (timestamp / 60) % 60;
    int second = timestamp % 60;

    if (hour >= 0 && hour < 24 && minute >= 0 && minute < 60 && second >= 0 && second < 60) {
        // If the timestamp is within the range, print the message
        System.out.println(message);
        return true;
    } else {
        // If the timestamp is not within the range, do not print the message
        return false;
    }
}

public boolean shouldPrintMessage(int timestamp, String message) {
    if (message == null || message.isEmpty()) {
        return false;
    }

    // Calculate the current time in seconds
    int currentTime = (int) (System.currentTimeMillis() / 1000);

    // Return true if the timestamp is in the future or it's the same as the current time
    return timestamp > currentTime || timestamp == currentTime;
}

public boolean shouldPrintMessage(int timestamp, String message) {
    // Check if the timestamp is a valid value
    if (timestamp < 0) {
        throw new IllegalArgumentException("Timestamp must be a positive integer");
    }

    // Check if the message is null or empty
    if (message == null || message.isEmpty()) {
        throw new IllegalArgumentException("Message must not be null or empty");
    }

    // Check if the current time is within the allowed time range
    if (timestamp < System.currentTimeMillis() - 10) {
        return false;
    }

    // Check if the message should be printed based on the timestamp
    if (timestamp % 3 == 0) {
        return false;
    }

    // All checks passed, return true
    return true;
}

