private static boolean startsWith(String str, String prefix, boolean ignoreCase) {
    if (str == null || prefix == null) {
        return false;
    }
    if (ignoreCase) {
        return str.toLowerCase().startsWith(prefix.toLowerCase());
    }
    return str.startsWith(prefix);
}

private static boolean startsWith(String str, String prefix, boolean ignoreCase) {
    if (str == null || prefix == null) {
        return str == null && prefix == null;
    }
    return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
}

private static boolean startsWith(final String str,final String prefix,final boolean ignoreCase) {
    if(str == null || prefix == null) {
        // If both string and prefix are null, return null
        return false;
    }

    if(ignoreCase) {
        // Convert both to lowercase for ignore case check
        str = str.toLowerCase();
        prefix = prefix.toLowerCase();
    }

    // Check if the string starts with the prefix (case ignored)
    return str.startsWith(prefix);
}

public static boolean startsWith(String str, String prefix, boolean ignoreCase) {
    if (str == null || prefix == null) {
        return str == null && prefix == null;
    }
    if (ignoreCase) {
        return str.toLowerCase().startsWith(prefix.toLowerCase());
    } else {
        return str.startsWith(prefix);
